pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address beneficiary) internal {
        uint balBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint cBalAfter;
        uint cCountAfter;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        cBalAfter = address(c).balance;
        try c.depositsCount() returns (uint256 __r) { cCountAfter = __r; } catch { return; }
        assertTrue(!reverted ||
            (msg.sender != c.owner() &&
             cBalAfter == balBefore &&
             cCountAfter == countBefore));
    }

